package com.bank.flink.deploy;

// Describes a streaming workload's profile and constraints.
class Workload {
    final String name;
    final boolean variableLoad;        // spiky vs steady
    final boolean smallOpsTeam;        // cannot staff 24x7 cluster ops
    final boolean needsAwsIntegration; // S3/Glue/Lambda/CloudWatch
    final boolean needsDeepCustomization; // specific version/plugin/tuning

    Workload(String name, boolean variableLoad, boolean smallOpsTeam,
             boolean needsAwsIntegration, boolean needsDeepCustomization) {
        this.name = name;
        this.variableLoad = variableLoad;
        this.smallOpsTeam = smallOpsTeam;
        this.needsAwsIntegration = needsAwsIntegration;
        this.needsDeepCustomization = needsDeepCustomization;
    }
}
