package com.bank.flink.deploy;

import java.util.logging.Logger;

// Compares deployments for a workload and recommends one with reasons.
class DeploymentAdvisor {
    private static final Logger log = Logger.getLogger(DeploymentAdvisor.class.getName());

    private final SelfManagedFlink self = new SelfManagedFlink();
    private final ManagedFlink managed = new ManagedFlink();

    FlinkDeployment recommend(Workload w) {
        // Advantages of managed for this workload.
        if (w.smallOpsTeam)
            log.info(() -> "small ops team -> managed removes " + self.operationalEffort()
                    + "/10 operational effort (managed is " + managed.operationalEffort() + "/10)");
        if (w.variableLoad && managed.autoScales())
            log.info("variable load -> managed autoscaling is cost-effective (pay-per-use)");
        if (w.needsAwsIntegration && managed.seamlessAwsIntegration())
            log.info("needs AWS integration -> managed wires S3/Glue/Lambda/CloudWatch natively");

        // Trade-offs to weigh.
        if (managed.operationalLockIn())
            log.warning("trade-off: operational lock-in (but application code stays portable)");
        if (!managed.fullCustomization())
            log.warning("trade-off: reduced customization (curated config, not every Flink knob)");

        // Decision: deep customization need tips to self-managed; else managed.
        FlinkDeployment chosen = w.needsDeepCustomization ? self : managed;
        log.info(() -> "RECOMMEND for '" + w.name + "' => " + chosen.name());
        return chosen;
    }
}
